// Generated by Rowlit from SQLite: CustomerOrders. Review before use.
package com.example.shop.jpa_sqlite;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import javax.sql.DataSource;

/** Runs the CustomerOrders query. Named parameters are bound by position (JDBC uses ?). */
public final class CustomerOrdersQuery {
    private static final String SQL = """
            SELECT c.id, c.name, o.total, o.order_date
            FROM customers c
            JOIN orders o ON o.customer_id = c.id
            WHERE c.id = ? AND o.total > ?
            ORDER BY o.order_date DESC""";

    private final DataSource dataSource;

    public CustomerOrdersQuery(DataSource dataSource) {
        this.dataSource = Objects.requireNonNull(dataSource, "dataSource");
    }

    public List<CustomerOrdersRow> run(Integer p1, Double p2) throws SQLException {
        try (Connection c = dataSource.getConnection();
                PreparedStatement ps = c.prepareStatement(SQL)) {
            ps.setObject(1, p1, Types.INTEGER);
            ps.setObject(2, p2, Types.DOUBLE);
            try (ResultSet rs = ps.executeQuery()) {
                List<CustomerOrdersRow> list = new ArrayList<>();
                while (rs.next()) {
                    list.add(new CustomerOrdersRow(
                            rs.getInt("id"),
                            rs.getString("name"),
                            rs.getDouble("total"),
                            rs.getString("order_date")));
                }
                return list;
            }
        }
    }
}
